import { validatePluginName } from '../../../../src/plugins/shape/name.js';

describe('validatePluginName', () => {
  const PREFIX = 'modern-errors-';

  test('should add fullName property with prefix when plugin name is valid', () => {
    const plugin = { name: 'testplugin' };
    const result = validatePluginName(plugin);

    expect(result).toEqual({
      ...plugin,
      fullName: `${PREFIX}${plugin.name}`
    });
    expect(result).not.toBe(plugin);
  });

  test('should preserve all original properties when adding fullName', () => {
    const plugin = { 
      name: 'testplugin',
      version: '1.0.0',
      config: { enabled: true },
      other: 'property'
    };

    const result = validatePluginName(plugin);

    expect(result).toEqual({
      ...plugin,
      fullName: `${PREFIX}${plugin.name}`
    });
  });

  test('should throw TypeError when plugin is missing name property', () => {
    const plugin = { version: '1.0.0' };

    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  test('should throw TypeError when plugin name is not a string', () => {
    const testCases = [
      { name: 123 },
      { name: null },
      { name: undefined },
      { name: {} },
      { name: [] },
      { name: true }
    ];

    testCases.forEach(plugin => {
      expect(() => validatePluginName(plugin)).toThrow(TypeError);
    });
  });

  test('should throw TypeError when name is empty string', () => {
    const plugin = { name: '' };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  test('should throw TypeError when name contains invalid characters', () => {
    const invalidNames = [
      'test-plugin',
      'test@plugin',
      'test plugin',
      'TestPlugin',
      'TESTPLUGIN',
      'test.plugin'
    ];

    invalidNames.forEach(name => {
      const plugin = { name };
      expect(() => validatePluginName(plugin)).toThrow(TypeError);
      expect(() => validatePluginName(plugin)).toThrow('must only contain lowercase letters and digits');
    });
  });

  test('should not mutate original plugin object', () => {
    const originalPlugin = { 
      name: 'testplugin',
      version: '1.0.0'
    };
    const pluginCopy = { ...originalPlugin };

    validatePluginName(originalPlugin);

    expect(originalPlugin).toEqual(pluginCopy);
    expect(originalPlugin).not.toHaveProperty('fullName');
  });

  test('should work with plugin that has nested objects', () => {
    const plugin = {
      name: 'testplugin',
      deep: {
        nested: {
          value: 'test'
        }
      }
    };

    const result = validatePluginName(plugin);

    expect(result).toEqual({
      ...plugin,
      fullName: `${PREFIX}${plugin.name}`
    });
    expect(result.deep).toEqual(plugin.deep);
  });

  test('should handle name with valid lowercase letters and digits', () => {
    const validNames = [
      'testplugin',
      'test123',
      'plugin123',
      'testplugin123',
      'abc123def',
      'plugin'
    ];

    validNames.forEach(name => {
      const plugin = { name };
      const result = validatePluginName(plugin);
      expect(result.fullName).toBe(`${PREFIX}${name}`);
    });
  });

  test('should throw TypeError for name with uppercase letters', () => {
