const applyPluginProperties = require('../../../../src/plugins/properties/main.js').applyPluginProperties;

describe('applyPluginProperties', () => {
  let error;
  let plugin;
  let plugins;

  beforeEach(() => {
    error = { message: 'Test error' };
    plugin = {
      fullName: 'test-plugin',
      properties: jest.fn().mockReturnValue({ additionalInfo: 'plugin data' })
    };
    plugins = [{ fullName: 'other-plugin' }];
  });

  it('should apply plugin properties to error object', () => {
    applyPluginProperties(error, plugin, plugins);

    expect(plugin.properties).toHaveBeenCalledWith(error, plugin, plugins);
    expect(error).toEqual({
      message: 'Test error',
      additionalInfo: 'plugin data'
    });
  });

  it('should not modify error when properties returns undefined', () => {
    plugin.properties.mockReturnValue(undefined);
    const originalError = { ...error };

    applyPluginProperties(error, plugin, plugins);

    expect(error).toEqual(originalError);
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should not modify error when properties returns null', () => {
    plugin.properties.mockReturnValue(null);
    const originalError = { ...error };

    applyPluginProperties(error, plugin, plugins);

    expect(error).toEqual(originalError);
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should throw TypeError when properties returns non-plain object', () => {
    const date = new Date();
    plugin.properties.mockReturnValue(date);

    expect(() => {
      applyPluginProperties(error, plugin, plugins);
    }).toThrow(TypeError);
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should throw TypeError when properties returns array', () => {
    plugin.properties.mockReturnValue(['array', 'value']);

    expect(() => {
      applyPluginProperties(error, plugin, plugins);
    }).toThrow(TypeError);
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should throw TypeError when properties returns function', () => {
    plugin.properties.mockReturnValue(() => {});

    expect(() => {
      applyPluginProperties(error, plugin, plugins);
    }).toThrow(TypeError);
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should merge multiple properties into error object', () => {
    plugin.properties.mockReturnValue({
      prop1: 'value1',
      prop2: 'value2',
      nested: { key: 'val' }
    });

    applyPluginProperties(error, plugin, plugins);

    expect(error).toEqual({
      message: 'Test error',
      prop1: 'value1',
      prop2: 'value2',
      nested: { key: 'val' }
    });
  });

  it('should handle empty properties object', () => {
    plugin.properties.mockReturnValue({});

    applyPluginProperties(error, plugin, plugins);

    expect(error).toEqual({ message: 'Test error' });
    expect(plugin.properties).toHaveBeenCalled();
  });

  it('should pass correct arguments to properties function', () => {
    const mockProperties = jest.fn().mockReturnValue({});
    plugin.properties = mockProperties;

    applyPluginProperties(error, plugin, plugins);

    expect(mockProperties).toHaveBeenCalledWith(error, plugin, plugins);
  });

  it('should not modify original plugin object', () => {
    const originalPlugin = { ...plugin };
    const originalProperties = plugin.properties;

    applyPluginProperties(error, plugin, plugins);

    expect(plugin).toEqual(originalPlugin);
    expect(plugin.properties).toBe(originalProperties);
  });

  it('should not modify plugins array', () => {
    const originalPlugins = [...plugins];

    applyPluginProperties(error, plugin, plugins);

    expect(plugins).toEqual(originalPlugins);
  });

  it('should override existing error properties with plugin properties', () => {
    error.existing = 'old value';
    plugin.properties.mockReturnValue({ existing: 'new value' });

    applyPluginProperties(error, plugin, plugins);

    expect(error.existing).toBe('new value');
  });
});

