    const invalidMethodNames = [null, undefined, 123, {}, [], jest.fn()];

    invalidMethodNames.forEach(invalidName => {
      expect(() => {
        addInstanceMethod(mockPlugin, mockPlugins, ErrorClass, invalidName, methodFunc);
      }).toThrow(TypeError);
    });
  });

