const mergePrefixedError = (error) => {
  const { cause } = error
  const oldMessage = prefixCause(cause)
  const errorA = mergeErrorCause(error)

  if (cause !== errorA) {
    undoPrefixCause(cause, oldMessage)
  }

  return errorA
}

