    const result = mergeOpt(oldOpt, undefined);
    expect(result).toBe(oldOpt);
  });

  test('should return newOpt when it is not a plain object', () => {
    const oldOpt = { a: 1 };
    const newOpt = 'new value';
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toBe(newOpt);
  });

  test('should return newOpt when it is an array', () => {
    const oldOpt = { a: 1 };
    const newOpt = [1, 2, 3];
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toBe(newOpt);
  });

  test('should return newOpt when it is null', () => {
    const oldOpt = { a: 1 };
    const newOpt = null;
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toBe(newOpt);
  });

  test('should return newOpt when oldOpt is not a plain object', () => {
    const oldOpt = 'old value';
    const newOpt = { b: 2 };
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toBe(newOpt);
  });

