        expect(cloned.a.b).not.toBe(original.a.b);
        expect(cloned.d).not.toBe(original.d);
        expect(cloned.d[2]).not.toBe(original.d[2]);
    });

    test('should preserve property descriptors', () => {
        const original = {};
        Object.defineProperty(original, 'a', {
            value: 1,
            writable: false,
            enumerable: false,
            configurable: true
        });
        Object.defineProperty(original, 'b', {
            value: 2,
            writable: true,
            enumerable: true,
            configurable: false
        });
        const cloned = deepCloneObject(original);
        const descriptorA = Object.getOwnPropertyDescriptor(cloned, 'a');
        const descriptorB = Object.getOwnPropertyDescriptor(cloned, 'b');
        expect(descriptorA.value).toBe(1);
        expect(descriptorA.writable).toBe(false);
        expect(descriptorA.enumerable).toBe(false);
        expect(descriptorA.configurable).toBe(true);
        expect(descriptorB.value).toBe(2);
        expect(descriptorB.writable).toBe(true);
        expect(descriptorB.enumerable).toBe(true);
        expect(descriptorB.configurable).toBe(false);
    });

    test('should handle arrays correctly', () => {
        const original = [1, 2, { a: 3 }];
        const cloned = deepCloneObject(original);
        expect(cloned).toEqual(original);
        expect(cloned).not.toBe(original);
        expect(cloned[2]).not.toBe(original[2]);
    });

    test('should handle primitive values', () => {
        const original = { a: 123, b: 'string', c: null, d: undefined };
        const cloned = deepCloneObject(original);
        expect(cloned).toEqual(original);
        expect(cloned).not.toBe(original);
    });

    test('should maintain Symbol keys', () => {
        const sym = Symbol('test');
        const original = { [sym]: 'value', a: 1 };
        const cloned = deepCloneObject(original);
        expect(cloned[sym]).toBe('value');
        expect(cloned).toEqual(original);
        expect(cloned).not.toBe(original);
    });

