        const inner = { x: 1 };
        const original = { a: inner };
        const cloned = deepCloneObject(original);
        cloned.a.x = 2;
        expect(original.a.x).toBe(1);
    });

    test('should handle empty objects', () => {
        const original = {};
        const cloned = deepCloneObject(original);
        expect(cloned).toEqual(original);
        expect(cloned).not.toBe(original);
    });

    test('should clone object with getter and setter', () => {
        const original = {
            _value: 0,
            get value() { return this._value; },
            set value(val) { this._value = val; }
        };
        const cloned = deepCloneObject(original);
        expect(cloned.value).toBe(0);
        cloned.value = 5;
        expect(cloned.value).toBe(5);
        expect(original.value).toBe(0);
    });

