  const mockNormalizeMethod = jest.fn(method => ({ normalized: method }));
  const mockNormalizeStaticMethods = jest.fn((plugin, normalizedInstanceMethods) => 
    ({ ...plugin, statics: normalizedInstanceMethods })
  );

  const INSTANCE_METHODS = ['draw', 'update', 'delete'];
