        throw new TypeError('Plugin must be an object');
      }

      // Normalize instance methods
      const normalizedInstanceMethods = {};
      INSTANCE_METHODS.forEach(method => {
        if (plugin.instanceMethods && plugin.instanceMethods[method]) {
          normalizedInstanceMethods[method] = mockNormalizeMethod(plugin.instanceMethods[method]);
        }
      });

      // Normalize static methods using normalized instance methods
      return mockNormalizeStaticMethods(plugin, normalizedInstanceMethods);
    },
    normalizeMethod: mockNormalizeMethod,
    normalizeStaticMethods: mockNormalizeStaticMethods,
    INSTANCE_METHODS,
    STATIC_METHODS
  };
