      }).toThrow(TypeError);
    });

    test('should throw TypeError when plugins is boolean', () => {
      expect(() => {
        normalizePluginsOpt(MockError, true);
      }).toThrow(TypeError);
    });

    test('should throw TypeError when plugins is a function', () => {
      expect(() => {
        normalizePluginsOpt(MockError, () => {});
      }).toThrow(TypeError);
    });

    test('should include ParentError name in error message', () => {
